import sys
import os
import hashlib

def parse_label(label):
    if not label or not label[0].isalpha() and not label[0] == '_':
        return None
    for c in label[1:]:
        if not c.isalnum() and c != '_':
            return None
    return label

def evaluate_expression(expr, labels):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i] == '(':
            tokens.append('(')
            i += 1
        elif expr[i] == ')':
            tokens.append(')')
            i += 1
        elif expr[i] in '+-*/%':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            if expr[i] in labels:
                tokens.append(expr[i])
                i += 1
            else:
                return None
    return tokens

def evaluate(tokens, labels):
    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == '(':
            stack.append(token)
            i += 1
        elif token == ')':
            while stack and stack[-1] != '(':
                stack.append(evaluate_subexpression(stack, labels))
            stack.pop()  # Remove '('
            i += 1
        elif token in '+-*/%':
            left = evaluate_subexpression(stack, labels)
            stack.append(left)
            while stack and stack[-1] != '(' and (stack[-1] in '+-*/%' or stack[-1] == ')'):
                right = evaluate_subexpression(stack, labels)
                stack.append(apply_operator(stack.pop(), stack.pop(), right))
            stack.append(token)
            i += 1
        else:
            stack.append(int(token) if token.isdigit() else labels[token])
            i += 1
    return evaluate_subexpression(stack, labels)

def evaluate_subexpression(stack, labels):
    while len(stack) >= 2 and stack[-1] != '(':
        op = stack.pop()
        right = stack.pop()
        left = stack.pop()
        stack.append(apply_operator(op, left, right))
    return stack[0] if stack else None

def apply_operator(op, left, right):
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '//':
        return left // right
    elif op == '%':
        return left % right
    return None

def compute_digest(lines, key):
    data = []
    for line in lines:
        if line.strip():
            parts = line.split()
            if len(parts) == 2:
                label, value = parts
                data.append(f"{label}={value}")
    data_str = '\n'.join(data)
    digest = hashlib.sha256((data_str + key).encode()).hexdigest()
    return digest

