import sys
import re
import os
from collections import defaultdict

def validate_label(label):
    if not re.fullmatch(r'^[a-zA-Z_][a-zA-Z0-9_]*$', label):
        raise ValueError(f"Invalid label: {label}")

def evaluate_expression(expr, labels):
    try:
        # Replace labels with their values
        for label, value in labels.items():
            expr = expr.replace(label, str(value))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'__import__': None})
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

def compute_digest(lines, key):
    values = {}
    for line in lines:
        if not line.strip():
            continue
        parts = line.split(maxsplit=1)
        if len(parts) != 2:
            continue
        label, expr = parts
        validate_label(label)
        value = evaluate_expression(expr, values)
        values[label] = value

    # Prepare data for digest
    data = []
    for label, value in values.items():
        data.append(f"{label}={value}")
    data.append(f"digest_key={key}")

    # Compute SHA-256 hash of the concatenated data
    digest = hashlib.sha256('\n'.join(data).encode()).hexdigest()
    return digest

def main():
    if len(sys.argv) != 2:
        print("Usage: python ledger.py <path>", file=sys.stderr)
        sys.exit(1)

    path = sys.argv[1]
    if not os.path.exists(path):
        print(f"Error: File not found: {path}", file=sys.stderr)
        sys.exit(1)

    with open(path, 'r') as f:
        lines = [line.strip() for line in f if line.strip()]

    labels = {}
    for line in lines:
        parts = line.split(maxsplit=1)
        if len(parts) != 2:
            continue
        label, expr = parts
        validate_label(label)
        value = evaluate_expression(expr, labels)
        print(f"{label}={value}")
        labels[label] = value

    key = os.getenv('LEDGER_KEY', '')
    digest = compute_digest(lines, key)
    print(f"digest={digest}")

if __name__ == "__main__":
    import hashlib
    main()
